# dict_intersect :: ({'a': 1, 'b': 2}, {'b': 3, 'c': 4})
def dict_intersect(a, b):
    return {k: a[k] for k in a if k in b}

if __name__ == '__main__':
    print(dict_intersect(({'a': 1, 'b': 2}, {'b': 3, 'c': 4})))

